import {useEffect,useRef,type ReactNode} from "react";
import {Platform,View,type ViewProps} from "react-native";
import {createDragController,type DragController} from "@/components/nyc-tron/ui/components/gestures/drag-controller";
import {keyboardKey,type DragPoint,type DragTransport,type KeyEventLike} from "@/components/nyc-tron/ui/components/gestures/drag-transport";
import {PanResponderDrag} from "@/components/nyc-tron/ui/components/gestures/PanResponderDrag";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {space,border,opacity,size} from "@/components/nyc-tron/ui/tokens";

// Web only: a drag otherwise selects nearby text. Not a ViewStyle key in RN.
const NO_SELECT=(Platform.OS==="web"?{userSelect:"none"}:{}) as object;

export type {DragPoint} from "@/components/nyc-tron/ui/components/gestures/drag-transport";

/** Props for {@linkcode DragGrabHandle}. */
export interface DragGrabHandleProps extends Omit<ViewProps,"children"|"accessibilityLabel"> {
  /** Screen-reader name, e.g. "Reorder Layer 2". */
  label:string;
  disabled?:boolean;
  /** A drag began. The app records what is being dragged. */
  onStart:()=>void;
  /** Preview only. Called for each one-pointer move; never commit here. */
  onMove:(point:DragPoint)=>void;
  /** Exactly once per completed drag. */
  onCommit:()=>void;
  /** Escape, termination, a second pointer or becoming disabled. The app restores its preview. */
  onCancel:()=>void;
  /** Pointer recogniser. @default PanResponderDrag */
  transport?:DragTransport;
  /** Glyph color override; defaults to the theme's muted text token. */
  color?:string;
  /** Replaces the default three-bar grip glyph. */
  children?:ReactNode;
  className?:string;
  unstyled?:boolean;
}

/**
 * Controlled 44x44 drag handle for docking, reordering and similar list moves. It
 * reports start, preview moves, one commit and cancellation; the app owns every
 * position and the resulting order.
 */
export function DragGrabHandle({
  label,disabled=false,onStart,onMove,onCommit,onCancel,transport:Transport=PanResponderDrag,
  color,children,className,unstyled=false,style,...rest
}:DragGrabHandleProps){
  const latest=useRef({disabled,onStart,onMove,onCommit,onCancel});
  latest.current={disabled,onStart,onMove,onCommit,onCancel};
  const controllerRef=useRef<DragController|null>(null);
  if(!controllerRef.current)controllerRef.current=createDragController({
    disabled:()=>latest.current.disabled,
    start:()=>latest.current.onStart(),
    move:point=>latest.current.onMove(point),
    commit:()=>latest.current.onCommit(),
    cancel:()=>latest.current.onCancel(),
  });
  const controller=controllerRef.current;
  useEffect(()=>()=>controller.cancel(),[controller]);
  const onKeyDown=(event:KeyEventLike)=>{if(keyboardKey(event)==="Escape")controller.cancel();};
  // Bars are drawn as top borders: forced-colors mode repaints backgrounds to
  // Canvas but keeps borders visible in CanvasText.
  const bar=color?{borderColor:color}:null;
  const grip=children ?? <View pointerEvents="none" style={{gap:space[0.75]}}>
    {[0,1,2].map(i=><View key={i} {...{className:joinClasses(!unstyled&&!color&&"border-text-muted")}}
      style={{width:16,height:0,borderTopWidth:border[2],...bar}}/>)}
  </View>;
  return <Transport disabled={disabled}
    onBegin={()=>controller.begin()}
    onMove={(point,touches)=>{if(touches===1)controller.move(point);else controller.cancel();}}
    onRelease={()=>controller.release()}
    onCancel={()=>controller.cancel()}>
    <View {...rest} collapsable={false}
      {...{onKeyDown,className:joinClasses(!unstyled&&"rounded-control",className)}}
      accessible accessibilityLabel={label}
      accessibilityHint="Drag to move. Press Escape to cancel."
      aria-disabled={disabled}
      // Not a tab stop (there is no keyboard move), but pressing it focuses it,
      // so Escape reaches onKeyDown while the pointer is down on web.
      focusable={false}
      style={[{minWidth:size.touch,minHeight:size.touch,justifyContent:"center",alignItems:"center",opacity:disabled?opacity[40]:1,...NO_SELECT},style]}>
      {grip}
    </View>
  </Transport>;
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

